import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Object3D,
    PointLight,
    DirectionalLight,
    Box3,
    Vector3
  } = THREE;

  const root = new Group();
  root.name = config.id || config.name || 'features-thumbnail-card';
  root.userData.handlers = {};

  const ownedResources = [];
  const primitiveResults = [];
  const timelines = [];
  let disposed = false;

  const own = (resource) => {
    if (resource) ownedResources.push(resource);
    return resource;
  };

  const makeStandard = (params) => {
    const material = new MeshStandardNodeMaterial(params);
    own(material);
    return material;
  };

  const makeBasic = (params) => {
    const material = new MeshBasicNodeMaterial(params);
    own(material);
    return material;
  };

  const backdropMaterial = makeBasic();
  backdropMaterial.colorNode = mix(
    color('#0b0b10'),
    mix(color('#16161d'), color('#e8ecf2'), uv().y),
    uv().y
  );

  const backdrop = new Mesh(
    own(new PlaneGeometry(7, 6)),
    backdropMaterial
  );
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const cardMaterial = makeStandard({
    color: '#16161d',
    roughness: 0.68,
    metalness: 0.42
  });

  const card = new Mesh(
    own(new BoxGeometry(3.15, 2.15, 0.16)),
    cardMaterial
  );
  card.name = 'machined-thumbnail-card';
  card.position.set(0, 0, -0.18);
  root.add(card);

  const stripMaterial = makeStandard({
    color: '#0b0b10',
    roughness: 0.62,
    metalness: 0.3
  });

  const captionStrip = new Mesh(
    own(new BoxGeometry(3.15, 0.42, 0.2)),
    stripMaterial
  );
  captionStrip.name = 'caption-strip';
  captionStrip.position.set(0, -0.865, -0.02);
  root.add(captionStrip);

  const accentMaterial = makeStandard({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.15,
    roughness: 0.55,
    metalness: 0.45
  });

  const accentBar = new Mesh(
    own(new BoxGeometry(2.55, 0.035, 0.035)),
    accentMaterial
  );
  accentBar.name = 'signal-red-caption-accent';
  accentBar.position.set(-0.18, -0.66, 0.12);
  root.add(accentBar);

  const shadowMaterial = makeBasic({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });

  const contactShadow = new Mesh(
    own(new CircleGeometry(1.65, 48)),
    shadowMaterial
  );
  contactShadow.name = 'radial-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(1.35, 0.42, 1);
  contactShadow.position.set(0, -1.17, -0.08);
  root.add(contactShadow);

  const rimLight = new PointLight('#ff2a38', 0.78, 5.5, 2);
  rimLight.name = 'accent-rim-light';
  rimLight.position.set(1.65, 1.25, 1.9);
  root.add(rimLight);

  const fillLight = new DirectionalLight('#e8ecf2', 0.42);
  fillLight.name = 'paper-fill-light';
  fillLight.position.set(-2.2, 1.8, 2.4);
  fillLight.target.position.set(0, 0, 0);
  root.add(fillLight);
  root.add(fillLight.target);

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    root.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power3.out' }
  );
  entrance.to(
    root.scale,
    { x: 1, y: 1, z: 1, duration: 0.48, ease: 'power4.out' }
  );
  timelines.push(entrance);
  entrance.play();

  const hoverRise = gsap.timeline({ paused: true });
  hoverRise.to(root.position, {
    y: '+=0.15',
    duration: 0.3,
    ease: 'power2.out'
  });
  timelines.push(hoverRise);

  root.userData.handlers.hover = (active) => {
    const isActive =
      active === true ||
      active?.active === true ||
      active?.type === 'enter' ||
      active?.phase === 'enter';

    if (isActive) {
      hoverRise.play();
      gsap.to(root.rotation, {
        z: -0.025,
        duration: 0.3,
        ease: 'power2.out'
      });
    } else {
      hoverRise.reverse();
      gsap.to(root.rotation, {
        z: 0,
        duration: 0.3,
        ease: 'power2.out'
      });
    }
  };

  root.userData.handlers.click = () => {
    const press = gsap.timeline();
    press.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    });
    press.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.32,
      ease: 'back.out(2)'
    });
    timelines.push(press);
    ctx.emit('hub-features.select', {
      id: config.id || config.name || 'features-thumbnail-card'
    });
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  const meshUrl = config.meshUrl;
  if (meshUrl && ctx.glbLoader?.loadGLB) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;

      const subject = gltf.scene;
      subject.name = 'orrery-gear-subject';

      const bounds = new Box3().setFromObject(subject);
      const size = bounds.getSize(new Vector3());
      const center = bounds.getCenter(new Vector3());
      const largest = Math.max(size.x, size.y, size.z, 0.001);
      const fitScale = 1.62 / largest;

      subject.position.sub(center);
      subject.scale.setScalar(fitScale);
      subject.position.set(0, 0.12, 0.16);
      subject.rotation.set(0.03, -0.12, 0.02);

      root.add(subject);
      own(subject);
    }).catch(() => {});
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const item of material) item?.dispose?.();
      } else {
        material?.dispose?.();
      }
    });

    for (const resource of ownedResources) {
      if (resource !== root && resource?.dispose) resource.dispose();
    }

    root.clear();
  };

  return root;
}

export default createNode;
